    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best-Fit principle).
    // Lower post_residual means tighter packing.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily unless we are forced or it's very early.
        // If fitting_bins_count > 0, we have alternatives.
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        } else {
            // No choice, must open new bin.
            score -= 10.0;
        }
    } else {
        // We are using an existing bin.
        // Encourage packing that leaves space for the next item (Lookahead).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect: we leave enough room for the next item.
                score -= 15.0;
            } else {
                // Bad: this placement orphans the next item.
                score += 5.0;
            }
        }

        // Penalize creating "slivers" (very small residual) that are hard to fill.
        // A residual between 1 and 9 is usually useless for items >= 10.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Global state correction: if we have many open bins, prioritize filling 
        // the one with the smallest residual to consolidate (Best Fit).
        // If we have few bins, we are more flexible.
        score += (open_bins_count as f64) * 0.5;

        // If this bin's residual is significantly lower than the mean, 
        // it's a good candidate for consolidation.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Dynamic time horizon: as we approach the end of the stream, 
    // prioritize tighter packing (lower residuals) more aggressively.
    score += (progress * 10.0);

    score
