    // Base score: prioritize tighter fits (Best Fit principle).
    let mut score = post * post;

    // Penalty for leaving "fragmented" space that is too small for common future items.
    // We penalize residuals that are small but non-zero, specifically targeting the 
    // gap between 1 and 10, which is harder to fill.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powi(2) * 5.0;
