            score += 200.0 * (1.0 - progress);
        }
    }

    // Dynamics: As we approach the end of the stream, prioritize closing bins
    // by heavily penalizing keeping many bins open.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).powf(1.5) * progress * 10.0;
    }

    // Heuristic for new bins: Only open a new bin if the current fit is extremely poor
    // or if we are early in the stream and want to keep bins "fresh" for potential larger items.
    if bin_residual == bin_capacity {
        // This is the score for an empty bin.
        // We set a threshold: only pick this if the average fit quality is very low.
        score = 400.0 - (progress * 100.0) + (mean_residual * 0.5);
    } else {
        // Adjustment for bins that are nearly full, making them highly attractive.
        score -= (bin_capacity as f64 - post) * 0.1;
    }

    score
