pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (wasted space) quadratically.
    // We want to pack tightly, so lower post_residual is better.
    let mut score = post_res * post_res;

    // Lookahead interaction: If the next item is large, we want to reserve space.
    // If post_residual is smaller than the next item, we penalize it to force
    // usage of bins that can accommodate the next item.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post_res < next_item {
            score += (next_item - post_res) * 50.0;
        }
    }

    // Dynamic thresholding: as we progress through the stream, we become 
    // more conservative about opening new bins. 
    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as the stream progresses.
        // We only open a new bin if the existing fits are extremely poor.
        score += 2500.0 * (1.0 + progress);

        // If there are many fitting bins, opening a new one is highly discouraged.
        score += (fitting_bins_count as f64) * 1000.0;
    } else {
        // For existing bins, reward packing that keeps the bin residual 
        // near the global mean residual to maintain uniform bin utilization.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 10.0;
    }

    // Penalize fragmented open bins: if we have many open bins, 
    // favor filling the ones with the least residual.
    score += (open_bins_count as f64) * (100.0 - post_res);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
